for (const example of fixture.cases) {
  test('public wiki parity: ' + example.name, () => {
    const { base, bonus, hybrid, options, dungeon, coefs, expected } = example;
    const stats = engine.aggregateStats(base, bonus, hybrid);
    assert.deepEqual(stats, expected.stats, 'aggregated stats and hybrid bookkeeping');
    if (!hybrid) {
      const input = engine.referenceInput(stats, 'boss', dungeon, coefs.direct, { weaponAttrCoef: coefs.weapon, strMagMult: coefs.strMag });
      assert.deepEqual(input, expected.input, 'reference input');
      assert.deepEqual(engine.calculateReferenceDamage(input), expected.ranges, 'four possible damage ranges');
    }
    for (const scenario of ['theory', 'normal', 'boss']) {
      assert.equal(engine.calcDirectHitDamage(stats, coefs.direct, scenario, options, dungeon), expected.direct[scenario], scenario + ' direct');
      assert.equal(engine.calcPlacementDamage(stats, coefs.weapon, coefs.strMag, coefs.total, scenario, options, dungeon), expected.placement[scenario], scenario + ' placement');
    }
    assert.deepEqual(engine.calcHitIndicatorSummary(stats, base.isPhysicalJob), expected.hit, 'hit indicators');
    assert.deepEqual(engine.applyEnchantDelta(stats, engine.DEFAULT_ENCHANT_OPTION, fixture.newEnchant), expected.changed, 'enchant delta');
    assert.deepEqual(engine.compareEnchants(stats, engine.DEFAULT_ENCHANT_OPTION, fixture.newEnchant, coefs.direct, coefs.weapon, coefs.strMag, coefs.total, dungeon, options, { directHit: 1250, placementStrMag: 0.02, placementTotal: 0.08 }), expected.enchant, 'eight enchant comparisons');
    assert.deepEqual(engine.calcDirectHitEfficiencyDungeon(stats, coefs.direct, dungeon, 'boss', options.backAttackRate), expected.directEfficiency, 'dungeon direct efficiency');
    assert.deepEqual(engine.calcPlacementEfficiencyTheory(stats, coefs.weapon, coefs.strMag, options.backAttackRate), expected.placementEfficiency, 'theory placement efficiency');
  });
}

test('public wiki core coefficient thresholds and all 45 placement coefficients', () => {
  for (const row of fixture.coreLevels) assert.deepEqual(engine.calcPlacementCoreMultipliers(row.level), row.expected, 'core ' + row.level);
  for (const row of fixture.placement) assert.deepEqual(engine.calcPlacementSkillCoefficients(engine.placementSkills.find(skill => skill.id === row.id), row.level, row.core), row.expected, row.id);
});

test('skill lookups accept names, legacy names, and stable IDs', () => {
  assert.equal(engine.directHitSkills.length, 325);
  assert.equal(engine.placementSkills.length, 45);
  for (const [skills, find] of [[engine.directHitSkills, engine.findDirectHitSkill], [engine.placementSkills, engine.findPlacementSkill]]) {
    for (const skill of skills) {
      assert.equal(find(skill.job, skill.id), skill);
      assert.ok(find(skill.job, skill.name));
      for (const name of skill.legacyNames) assert.ok(find(skill.job, name));
    }
  }
});

test('invalid real-damage inputs fail visibly, including fractional caps', () => {
  const input = fixture.cases[0].expected.input;
  for (const delta of [{ guard: 100.1 }, { elasticity: 1000.1 }, { penetration: 100.1 }, { weaponMax: -1 }, { summonCoef: -100.1 }, { level: Infinity }, { mainStat: NaN }]) {
    assert.throws(() => engine.calculateReferenceDamage({ ...input, ...delta }), RangeError);
  }
  assert.doesNotThrow(() => engine.calculateReferenceDamage({ ...input, summonCoef: -100, penetration: 100, guard: 100, elasticity: 1000 }));
});

test('placement total multiplier is informational in the primary wiki engine', () => {
  const stats = engine.aggregateStats(engine.DEFAULT_BASE_STATS);
  assert.equal(engine.calcPlacementDamage(stats, 42, 1.48, 1, 'boss', true), engine.calcPlacementDamage(stats, 42, 1.48, 99, 'boss', true));
});

test('hybrid setting presets redistribute each side independently when one main stat is zero', () => {
  const base = { ...engine.DEFAULT_BASE_STATS, hybridStats: { physical: { strMagPlus: 914852 }, magical: { strMagPlus: 0 } } };
  const stats = engine.aggregateStats(base, engine.findSpecSummon('초신수').bonuses, true);
  const result = engine.compareSettings(stats, 4500, { weaponAttrCoef: 42, strMagMult: 1.1, totalMult: 1.1925 }, engine.dungeons[0]);
  // Golden values from applying each budget preset to each public-wiki combat
  // side independently, then averaging that source engine's four damage outputs.
  const expected = {
    current: { normalDirect: 83.70830370443329, bossDirect: 14.651118614537353, normalPlacement: 70.71165059164184, bossPlacement: 12.18739614661377 },
    extremeWeapon: { normalDirect: 83.38283920846253, bossDirect: 14.549808484066467, normalPlacement: 68.25367115668243, bossPlacement: 8.655684026351013 },
    weapon: { normalDirect: 83.94848699853455, bossDirect: 14.725880941080934, normalPlacement: 72.52557501690919, bossPlacement: 9.589658290281372 },
    balanced: { normalDirect: 84.70445673701813, bossDirect: 14.96119274370819, normalPlacement: 78.23476607590973, bossPlacement: 10.837868665312806 },
    strMag: { normalDirect: 85.28598417651978, bossDirect: 15.142203538453064, normalPlacement: 82.6264358930072, bossPlacement: 11.798029035155029 },
    extremeStrMag: { normalDirect: 85.60317776287872, bossDirect: 15.240939393482972, normalPlacement: 85.02188880146699, bossPlacement: 12.522864801038514 }
  };
  for (const [key, damage] of Object.entries(expected)) {
    assert.deepEqual(result[key].damage, damage, key + ' independent physical/magical damage average');
    assert.ok(Math.abs(result[key].dist.strMag / 100 + result[key].dist.weaponAttr - result.budget) < 1e-8, key + ' preserves total budget');
  }
});
